css:
.fmq-root{position:absolute;inset:0;overflow:hidden;background:var(--wa-bg, #05050a);z-index:5;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-size:16px;font-weight:400;font-style:normal;line-height:normal;letter-spacing:normal;color:var(--wa-text, #fff);text-align:left;text-transform:none;word-spacing:normal;-webkit-font-smoothing:antialiased}
.fmq-root,.fmq-root *,.fmq-root *::before,.fmq-root *::after{box-sizing:border-box}
.fmq-root *{margin:0;padding:0;border:0 solid transparent;background:none;font:inherit;color:inherit;text-decoration:none}
.fmq-root img{display:block;border:0;max-width:none}
.fmq-root > [data-node-id]{will-change:transform}
.fmq-root [hidden]{display:none!important}
.fmq-root [data-sh-theme="dark"]{display:none!important}
.fmq-root[data-theme="dark"] [data-sh-theme="dark"]{display:block!important}
.fmq-root[data-theme="dark"] [data-sh-theme="dark"]{display:none!important}
.fmq-root .fmq_n2144_1213{height:56px;position:relative;flex-shrink:0;width:154px}
.fmq-root .fmq_nI2144_1213_181_654{position:absolute;background-color:color-mix(in srgb, var(--wa-bg, rgb(255 255 255)) 80%, transparent);inset:0.16% 0.11% 0.16% 0;border-radius:20px;box-shadow:0px 10px 20px 0px rgba(0,0,0,0.1)}
.fmq-root .fmq_nI2144_1213_181_655{position:absolute;inset:0.16% 15.38% 0.16% 58.69%;background-image:linear-gradient(to left, color-mix(in srgb, var(--wa-surface, rgb(217 217 217)) 0%, transparent) 50%, var(--wa-surface, #d7d7d7))}
.fmq-root .fmq_nI2144_1213_181_656{word-break:break-word;position:absolute;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:420;inset:35.64% 48.25% 34% 10.19%;line-height:17px;font-style:normal;color:var(--wa-text-sub, #464d5c);font-size:14px;text-align:center;white-space:nowrap;width:64px}
.fmq-root .fmq_nI2144_1213_181_657{word-break:break-word;position:absolute;font-family:"Pretendard Variable","Pretendard","Malgun Gothic",-apple-system,system-ui,sans-serif;font-weight:420;inset:35.64% 9.44% 34% 67.19%;line-height:17px;font-style:normal;color:var(--wa-text-sub, #464d5c);font-size:14px;text-align:center;white-space:nowrap;width:36px}
.fmq-root [data-name="Symbol/SPST (Horizontal) Wrap"] > * > [data-name="Glyph"] > [data-name="Glyph"]{transform-origin:0 0;transform:translate(0,15px) rotate(-90deg)}
.fmq-root{position:absolute;inset:0;background:transparent;z-index:auto;overflow:visible}
.fmq-root > [data-node-id="2144:1312"]{width:1080px;height:805px}
.fmq-root[data-theme="dark"]{color:var(--wa-point, #e3e9f2)}
.fmq-root[data-theme="dark"] [data-name="Button/Ack (Hover)"] p{color:var(--wa-text, #0e1a2c)!important}
.fmq-root[data-theme="dark"] [data-name="Frame 8"] > [data-name="logo chip"] img{filter:brightness(0) invert(1)!important}
.fmq-root[data-theme="dark"] [data-name="Frame 8"] > [data-name="WEMB Studio"]{color:var(--wa-text, #fff)!important}
.fmq-root[data-theme="dark"] :is([data-name="Side Panel (Left)"],[data-name="Side Panel (Right)"]) > [data-name="Panel Body"]{box-shadow:inset 0 0 0 1px rgba(255,255,255,.07),0 10px 30px rgba(0,0,0,.45)!important}
.fmq-root[data-theme="dark"] :is([data-name="Widget/Weather"] > [data-name="Row"],[data-name="Widget/Alarm Event"] > [data-name="Button Group"],[data-name="Widget/Mini Map"] > [data-name="Body"],[data-name="Widget/Plant Generation"] > [data-name="Body"],[data-name="Widget/Weekly Solar Generation"] > [data-name="Body"]){background:var(--wa-surface, #1f252e)!important;box-shadow:inset 0 0 0 1px rgba(255,255,255,.07),inset 0 1px 0 rgba(255,255,255,.05),0 6px 16px rgba(0,0,0,.35)!important}
.fmq-root[data-theme="dark"] :is([data-name="Widget/Alarm Event"],[data-name="Widget/Mini Map"]) > [data-name="Header"],.fmq-root[data-theme="dark"] :is([data-name="Widget/Plant Generation"],[data-name="Widget/Weekly Solar Generation"]) > [data-name="Body"] > [data-name="Header"]{background:linear-gradient(to top,var(--wa-point, #3b82ea),var(--wa-point, #1f5fcf))!important;box-shadow:0 4px 12px rgba(31,95,207,.35),inset 0 1px 0 rgba(255,255,255,.18)!important}
.fmq-root[data-theme="dark"] :is([data-name="Button/Solar"],[data-name="Button/Power Equipment"]) > [data-name="Body"] > [data-name="Background"]{background:linear-gradient(to right,color-mix(in srgb, var(--wa-point, rgb(59 130 234)) 55%, transparent) 28%,var(--wa-point, #2466d6) 62%)!important}
.fmq-root[data-theme="dark"] [data-name="Key Background"]{background:linear-gradient(to left,var(--wa-point, #3b82ea),var(--wa-point, #1f5fcf) 53%)!important}
.fmq-root[data-theme="dark"] [data-name^="Item/"] [data-name="Value"]{color:var(--wa-text, #f1f3f8)!important}
.fmq-root[data-theme="dark"] [data-name^="Direction/"] p,.fmq-root[data-theme="dark"] p[data-name^="Direction/"]{color:var(--wa-point, #1d2747)!important}
.fmq-root[data-theme="dark"] [data-name^="Meter Card/"] [data-name="Title"]{color:var(--wa-text, #0f1420)!important;font-weight:600}
.fmq-root[data-theme="dark"] [data-name="Badge/Critical"] p{color:var(--wa-danger, #ff5a57)!important}
.fmq-root[data-theme="dark"] [data-name^="Badge/"]:not([data-name$=" Wrap"]){background:var(--wa-surface, #232a35)!important}
.fmq-root[data-theme="dark"] [data-name^="Badge/"]:not([data-name$=" Wrap"])::after{border-color:color-mix(in srgb, var(--wa-line, rgb(255 255 255)) 12%, transparent)!important}
.fmq-root[data-theme="dark"] .fmq_nI2144_1213_181_654{background-color:color-mix(in srgb, var(--wa-surface, rgb(22 26 33)) 84%, transparent);box-shadow:0px 10px 20px 0px rgba(0,0,0,0.4)}
.fmq-root[data-theme="dark"] .fmq_nI2144_1213_181_655{background-image:linear-gradient(to left, color-mix(in srgb, var(--wa-surface, rgb(38 40 43)) 0%, transparent) 50%, var(--wa-surface, #27292c))}
.fmq-root[data-theme="dark"] .fmq_nI2144_1213_181_656{color:var(--wa-text-sub, #bfc2c6)}
.fmq-root[data-theme="dark"] .fmq_nI2144_1213_181_657{color:var(--wa-text-sub, #bfc2c6)}
